"""abacus: tpch/Q26; common numeric v4; explicitly rewritten workload.
Source: original/tpch/plop/Q26.sql
Run via experiments.validation.faithful_runtime; model settings are external.
"""
SYSTEM = 'abacus'
QUERY_ID = 'tpch/Q26'
SOURCE = 'original/tpch/plop/Q26.sql'

RELATIONAL_SQL = "WITH customer_sample AS MATERIALIZED (\n  SELECT\n    *\n  FROM customer\n  WHERE\n    c_acctbal > 500 AND c_mktsegment IN ('AUTOMOBILE', 'BUILDING', 'MACHINERY')\n), a_candidates AS (\n  SELECT\n    p.p_partkey,\n    p.p_name,\n    p.p_type,\n    p.p_brand\n  FROM part AS p\n  WHERE\n    SEMANTIC_FILTER(\n      'You are helping a retail analytics team pick products for customer demand analysis. From the name, type, and brand, does this item read like a marketable finished good rather than an upstream industrial input?\nPart Name: {0}\nPart Type: {1}\nBrand: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(p.p_name AS TEXT),\n      CAST(p.p_type AS TEXT),\n      CAST(p.p_brand AS TEXT)\n    )\n), s_candidates AS (\n  SELECT\n    s.s_suppkey,\n    s.s_name,\n    s.s_acctbal,\n    s.s_comment,\n    n.n_name AS supplier_nation,\n    r.r_name AS supplier_region\n  FROM supplier AS s\n  JOIN nation AS n\n    ON n.n_nationkey = s.s_nationkey\n  JOIN region AS r\n    ON r.r_regionkey = n.n_regionkey\n  WHERE\n    s.s_acctbal > 0\n    AND SEMANTIC_FILTER(\n      'You are shortlisting suppliers for stable operations. Based on supplier name style, account balance, comment, nation, and region, does this supplier look commercially dependable?\nSupplier Name: {0}\nAccount Balance: {1}\nComment: {2}\nNation: {3}\nRegion: {4}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(s.s_name AS TEXT),\n      CAST(s.s_acctbal AS TEXT),\n      CAST(s.s_comment AS TEXT),\n      CAST(n.n_name AS TEXT),\n      CAST(r.r_name AS TEXT)\n    )\n)\nSELECT\n  b.l_orderkey,\n  b.l_linenumber,\n  b.l_quantity,\n  b.l_extendedprice,\n  b.l_discount,\n  b.l_tax,\n  b.l_shipmode,\n  b.l_shipinstruct,\n  a.p_name,\n  a.p_type,\n  a.p_brand,\n  s.s_name,\n  s.supplier_nation,\n  s.supplier_region,\n  ps.ps_supplycost,\n  ps.ps_availqty,\n  c.c_custkey AS context_custkey,\n  c.c_name,\n  c.c_mktsegment,\n  c.c_acctbal\nFROM (\n  SELECT\n    l.l_orderkey,\n    l.l_linenumber,\n    l.l_partkey,\n    l.l_suppkey,\n    l.l_quantity,\n    l.l_extendedprice,\n    l.l_discount,\n    l.l_tax,\n    l.l_shipmode,\n    l.l_shipinstruct\n  FROM lineitem AS l\n  JOIN orders AS o\n    ON o.o_orderkey = l.l_orderkey\n  WHERE\n    l.l_shipdate >= CAST('1995-01-01' AS DATE)\n    AND l.l_shipdate < CAST('1997-01-01' AS DATE)\n    AND l.l_discount BETWEEN 0.05 AND 0.08\n    AND l.l_quantity BETWEEN 16 AND 24\n    AND l.l_shipmode IN ('AIR', 'REG AIR')\n    AND l.l_shipinstruct = 'DELIVER IN PERSON'\n    AND o.o_orderstatus = 'O'\n    AND o.o_orderpriority IN ('1-URGENT', '2-HIGH')\n    AND o.o_totalprice > 90000\n    AND SEMANTIC_FILTER(\n      'You are triaging enterprise orders for operations monitoring. From priority, total price, and comment, should this order be considered operationally important?\nOrder Priority: {0}\nTotal Price: {1}\nOrder Comment: {2}\nReturn a single YES or NO, with no other words. If uncertain, return YES.',\n      CAST(o.o_orderpriority AS TEXT),\n      CAST(o.o_totalprice AS TEXT),\n      CAST(o.o_comment AS TEXT)\n    )\n) AS b\nJOIN (\n  SELECT\n    ps.ps_partkey,\n    ps.ps_suppkey,\n    ps.ps_supplycost,\n    ps.ps_availqty\n  FROM partsupp AS ps\n  JOIN a_candidates AS a\n    ON a.p_partkey = ps.ps_partkey\n  JOIN s_candidates AS s\n    ON s.s_suppkey = ps.ps_suppkey\n  WHERE\n    ps.ps_supplycost BETWEEN 80 AND 900 AND ps.ps_availqty >= 50\n) AS ps\n  ON ps.ps_partkey = b.l_partkey AND ps.ps_suppkey = b.l_suppkey\nJOIN a_candidates AS a\n  ON a.p_partkey = b.l_partkey\nJOIN s_candidates AS s\n  ON s.s_suppkey = b.l_suppkey\nCROSS JOIN (\n  SELECT\n    *\n  FROM customer_sample AS c\n  WHERE\n    SEMANTIC_FILTER(\n      'You are tagging accounts for B2B revenue analysis. Based on customer name, market segment, account balance, and profile comment, does this customer look business-like and operationally relevant?\nCustomer Name: {0}\nMarket Segment: {1}\nAccount Balance: {2}\nComment: {3}\nReturn a single YES or NO, with no other words. If uncertain, return NO.',\n      CAST(c.c_name AS TEXT),\n      CAST(c.c_mktsegment AS TEXT),\n      CAST(c.c_acctbal AS TEXT),\n      CAST(c.c_comment AS TEXT)\n    )\n) AS c;\n"

def run(tables, job, semantic=None):
    from experiments.validation.faithful_runtime import run_relational
    return run_relational(SYSTEM, RELATIONAL_SQL, tables, job, semantic=semantic)

if __name__ == '__main__':
    from experiments.validation.faithful_runtime import query_main
    query_main(globals())
